      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      ruchang = -1,
      sentence = "Under the glittering glow of the star lights, his exquisite features still showed no hint of flinching.",
      next = {26}
    },
    [26] = {
