      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "I was starting to regret making this pact.",
      next = {27}
    },
    [27] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "The warm coat shielded me from the night wind, but I couldn't help inching closer to that familiar source of warmth.",
      next = {28}
    },
    [28] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "The instant the backs of our hands inadvertently touched, that cold gap in my heart was finally filled to the brim.",
      next = {29}
    },
    [29] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Tomorrow he had to go back to filming. I couldn't let all his effort getting into character go up in smoke.",
      next = {30}
    },
    [30] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Reason in my brain yanked at the controls like a madman, but my hand didn't want to listen to my brain's commands.",
      next = {31}
    },
    [31] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "I tentatively took a half step toward him again, pressing our arms against each other.",
      next = {32}
    },
    [32] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Our hands at our sides bumped in time with our strides, making my heart throb palpably; but Kiro seemed like he didn't notice anything.",
      next = {33}
    },
    [33] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "The reassuring warmth flowed into me like a warm stream, making me reluctant to let it go.",
      next = {34}
    },
    [34] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Just five more seconds—no, ten... then I'll separate.",
