      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "I counted ten seconds in my mind once, and then again. Neither of us took our hand away, as if we were both thinking the same thing.",
      next = {36}
    },
    [36] = {
      beijing = 4754,
      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Finally, when I was about to work up the nerve to step off, something hooked gently around my pinky.",
