      dialog = 3,
      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302108,
      role3 = 302205,
      sentence = "Maybe it was the lack of balance in my high heels, or it was my reason teetering on the brink of collapse from the wine, or perhaps... it was feeling a similar reluctance in him.",
