      music = "24_Romantic_Quiet",
      renwu = "npc",
      role1 = 326000,
      role2 = 302101,
      role3 = 302202,
      roleanim = 1.1,
      sentence = "With that thought, I half-faking, half-actually stumbled and fell toward him. Almost simultaneously, a force pulled on my wrist, and I fell into his arms.",
